module comp4(input A0,A1,A2,A3,B0,B1,B2,B3, output EQ); assign EQ = ({A3,A2,A1,A0} == {B3,B2,B1,B0}); endmodule

module comp8(input [7:0] A, input [7:0] B, output EQ); assign EQ = (A == B); endmodule

module d2_4e(input A0, input A1, input E, output D0, output D1, output D2, output D3);
  assign D0 = E & ({A1,A0} == 2'd0);
  assign D1 = E & ({A1,A0} == 2'd1);
  assign D2 = E & ({A1,A0} == 2'd2);
  assign D3 = E & ({A1,A0} == 2'd3);
endmodule

module d3_8e(input A0, input A1, input A2, input E, output D0, output D1, output D2, output D3, output D4, output D5, output D6, output D7);
  assign D0 = E & ({A2,A1,A0} == 3'd0);
  assign D1 = E & ({A2,A1,A0} == 3'd1);
  assign D2 = E & ({A2,A1,A0} == 3'd2);
  assign D3 = E & ({A2,A1,A0} == 3'd3);
  assign D4 = E & ({A2,A1,A0} == 3'd4);
  assign D5 = E & ({A2,A1,A0} == 3'd5);
  assign D6 = E & ({A2,A1,A0} == 3'd6);
  assign D7 = E & ({A2,A1,A0} == 3'd7);
endmodule

module d4_16e(input A0, input A1, input A2, input A3, input E, output D0, output D1, output D2, output D3, output D4, output D5, output D6, output D7, output D8, output D9, output D10, output D11, output D12, output D13, output D14, output D15);
  assign D0 = E & ({A3,A2,A1,A0} == 4'd0);
  assign D1 = E & ({A3,A2,A1,A0} == 4'd1);
  assign D2 = E & ({A3,A2,A1,A0} == 4'd2);
  assign D3 = E & ({A3,A2,A1,A0} == 4'd3);
  assign D4 = E & ({A3,A2,A1,A0} == 4'd4);
  assign D5 = E & ({A3,A2,A1,A0} == 4'd5);
  assign D6 = E & ({A3,A2,A1,A0} == 4'd6);
  assign D7 = E & ({A3,A2,A1,A0} == 4'd7);
  assign D8 = E & ({A3,A2,A1,A0} == 4'd8);
  assign D9 = E & ({A3,A2,A1,A0} == 4'd9);
  assign D10 = E & ({A3,A2,A1,A0} == 4'd10);
  assign D11 = E & ({A3,A2,A1,A0} == 4'd11);
  assign D12 = E & ({A3,A2,A1,A0} == 4'd12);
  assign D13 = E & ({A3,A2,A1,A0} == 4'd13);
  assign D14 = E & ({A3,A2,A1,A0} == 4'd14);
  assign D15 = E & ({A3,A2,A1,A0} == 4'd15);
endmodule

module m2_1(input D0, D1, S0, output O); assign O = S0 ? D1 : D0; endmodule

module m2_1e(input D0, D1, E, S0, output O); assign O = E & (S0 ? D1 : D0); endmodule

module m4_1e(input D0,D1,D2,D3,E,S0,S1, output O); wire [3:0] d={D3,D2,D1,D0}; assign O = E & d[{S1,S0}]; endmodule

module m8_1e(input D0,D1,D2,D3,D4,D5,D6,D7,E,S0,S1,S2, output O); wire [7:0] d={D7,D6,D5,D4,D3,D2,D1,D0}; assign O = E & d[{S2,S1,S0}]; endmodule

module rom16x1 #(parameter [15:0] INIT = 16'h0000)(input A0,A1,A2,A3, output O); assign O = INIT[{A3,A2,A1,A0}]; endmodule

module rom32x1 #(parameter [31:0] INIT = 32'h0)(input A0,A1,A2,A3,A4, output O); assign O = INIT[{A4,A3,A2,A1,A0}]; endmodule

module srl16 #(parameter [15:0] INIT = 16'h0000)(input A0,A1,A2,A3,CLK,D, output Q);
  reg [15:0] sr = INIT; always @(posedge CLK) sr <= {sr[14:0], D}; assign Q = sr[{A3,A2,A1,A0}]; endmodule

module ram16x1d #(parameter [15:0] INIT = 16'h0000)(input A0, A1, A2, A3, input DPRA0, DPRA1, DPRA2, DPRA3, input WCLK, WE, input D, output DPO, output SPO);
  reg [0:0] mem [0:15]; integer i; initial for (i=0;i<16;i=i+1) mem[i] = {1{INIT[i]}};
  wire [3:0] a = {A3,A2,A1,A0};
  always @(posedge WCLK) if (WE) mem[a] <= D;
  wire [3:0] dpra = {DPRA3,DPRA2,DPRA1,DPRA0};
  assign DPO = mem[dpra];
  assign SPO = mem[a];
endmodule

module ram16x1d_1 #(parameter [15:0] INIT = 16'h0000)(input A0, A1, A2, A3, input DPRA0, DPRA1, DPRA2, DPRA3, input WCLK, WE, input D, output DPO, output SPO);
  reg [0:0] mem [0:15]; integer i; initial for (i=0;i<16;i=i+1) mem[i] = {1{INIT[i]}};
  wire [3:0] a = {A3,A2,A1,A0};
  always @(negedge WCLK) if (WE) mem[a] <= D;
  wire [3:0] dpra = {DPRA3,DPRA2,DPRA1,DPRA0};
  assign DPO = mem[dpra];
  assign SPO = mem[a];
endmodule

module ram16x2d #(parameter [15:0] INIT = 16'h0000)(input A0, A1, A2, A3, input DPRA0, DPRA1, DPRA2, DPRA3, input WCLK, WE, input D0, input D1, output DPO0, output DPO1, output SPO0, output SPO1);
  reg [1:0] mem [0:15]; integer i; initial for (i=0;i<16;i=i+1) mem[i] = {2{INIT[i]}};
  wire [3:0] a = {A3,A2,A1,A0};
  always @(posedge WCLK) if (WE) mem[a] <= {D1,D0};
  wire [3:0] dpra = {DPRA3,DPRA2,DPRA1,DPRA0};
  assign DPO0 = mem[dpra][0];
  assign DPO1 = mem[dpra][1];
  assign SPO0 = mem[a][0];
  assign SPO1 = mem[a][1];
endmodule

module ram16x4d #(parameter [15:0] INIT = 16'h0000)(input A0, A1, A2, A3, input DPRA0, DPRA1, DPRA2, DPRA3, input WCLK, WE, input D0, input D1, input D2, input D3, output DPO0, output DPO1, output DPO2, output DPO3, output SPO0, output SPO1, output SPO2, output SPO3);
  reg [3:0] mem [0:15]; integer i; initial for (i=0;i<16;i=i+1) mem[i] = {4{INIT[i]}};
  wire [3:0] a = {A3,A2,A1,A0};
  always @(posedge WCLK) if (WE) mem[a] <= {D3,D2,D1,D0};
  wire [3:0] dpra = {DPRA3,DPRA2,DPRA1,DPRA0};
  assign DPO0 = mem[dpra][0];
  assign DPO1 = mem[dpra][1];
  assign DPO2 = mem[dpra][2];
  assign DPO3 = mem[dpra][3];
  assign SPO0 = mem[a][0];
  assign SPO1 = mem[a][1];
  assign SPO2 = mem[a][2];
  assign SPO3 = mem[a][3];
endmodule

module ram16x8d #(parameter [15:0] INIT = 16'h0000)(input A0, A1, A2, A3, input DPRA0, DPRA1, DPRA2, DPRA3, input WCLK, WE, input [7:0] D, output [7:0] DPO, output [7:0] SPO);
  reg [7:0] mem [0:15]; integer i; initial for (i=0;i<16;i=i+1) mem[i] = {8{INIT[i]}};
  wire [3:0] a = {A3,A2,A1,A0};
  always @(posedge WCLK) if (WE) mem[a] <= D;
  wire [3:0] dpra = {DPRA3,DPRA2,DPRA1,DPRA0};
  assign DPO = mem[dpra];
  assign SPO = mem[a];
endmodule

module ram16x2s #(parameter [15:0] INIT = 16'h0000)(input A0, A1, A2, A3, input WCLK, WE, input D0, input D1, output O0, output O1);
  reg [1:0] mem [0:15]; integer i; initial for (i=0;i<16;i=i+1) mem[i] = {2{INIT[i]}};
  wire [3:0] a = {A3,A2,A1,A0};
  always @(posedge WCLK) if (WE) mem[a] <= {D1,D0};
  assign O0 = mem[a][0];
  assign O1 = mem[a][1];
endmodule

module ram16x8s #(parameter [15:0] INIT = 16'h0000)(input A0, A1, A2, A3, input WCLK, WE, input [7:0] D, output [7:0] O);
  reg [7:0] mem [0:15]; integer i; initial for (i=0;i<16;i=i+1) mem[i] = {8{INIT[i]}};
  wire [3:0] a = {A3,A2,A1,A0};
  always @(posedge WCLK) if (WE) mem[a] <= D;
  assign O = mem[a];
endmodule

module ramb4_s8 #(parameter [255:0] INIT_00 = 256'h0, parameter [255:0] INIT_01 = 256'h0, parameter [255:0] INIT_02 = 256'h0, parameter [255:0] INIT_03 = 256'h0, parameter [255:0] INIT_04 = 256'h0, parameter [255:0] INIT_05 = 256'h0, parameter [255:0] INIT_06 = 256'h0, parameter [255:0] INIT_07 = 256'h0, parameter [255:0] INIT_08 = 256'h0, parameter [255:0] INIT_09 = 256'h0, parameter [255:0] INIT_0A = 256'h0, parameter [255:0] INIT_0B = 256'h0, parameter [255:0] INIT_0C = 256'h0, parameter [255:0] INIT_0D = 256'h0, parameter [255:0] INIT_0E = 256'h0, parameter [255:0] INIT_0F = 256'h0) (input [8:0] ADDR, input CLK, input [7:0] DI, input EN, input RST, input WE, output reg [7:0] DO);
  reg [7:0] mem [0:511];
  integer ii; initial begin
    for (ii=0; ii<32; ii=ii+1) mem[0+ii] = INIT_00[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[32+ii] = INIT_01[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[64+ii] = INIT_02[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[96+ii] = INIT_03[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[128+ii] = INIT_04[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[160+ii] = INIT_05[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[192+ii] = INIT_06[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[224+ii] = INIT_07[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[256+ii] = INIT_08[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[288+ii] = INIT_09[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[320+ii] = INIT_0A[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[352+ii] = INIT_0B[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[384+ii] = INIT_0C[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[416+ii] = INIT_0D[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[448+ii] = INIT_0E[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[480+ii] = INIT_0F[8*ii +: 8];
  end
  always @(posedge CLK) if (EN) begin
    if (RST) DO <= 8'h00;
    else if (WE) begin mem[ADDR] <= DI; DO <= DI; end
    else DO <= mem[ADDR];
  end
endmodule

module ramb4_s8_s8 #(parameter [255:0] INIT_00 = 256'h0, parameter [255:0] INIT_01 = 256'h0, parameter [255:0] INIT_02 = 256'h0, parameter [255:0] INIT_03 = 256'h0, parameter [255:0] INIT_04 = 256'h0, parameter [255:0] INIT_05 = 256'h0, parameter [255:0] INIT_06 = 256'h0, parameter [255:0] INIT_07 = 256'h0, parameter [255:0] INIT_08 = 256'h0, parameter [255:0] INIT_09 = 256'h0, parameter [255:0] INIT_0A = 256'h0, parameter [255:0] INIT_0B = 256'h0, parameter [255:0] INIT_0C = 256'h0, parameter [255:0] INIT_0D = 256'h0, parameter [255:0] INIT_0E = 256'h0, parameter [255:0] INIT_0F = 256'h0) (input [8:0] ADDRA, input CLKA, input [7:0] DIA, input ENA, input RSTA, input WEA, output reg [7:0] DOA,
                   input [8:0] ADDRB, input CLKB, input [7:0] DIB, input ENB, input RSTB, input WEB, output reg [7:0] DOB);
  (* ram_style = "distributed" *) reg [7:0] mem [0:511];   // the palette: a Block RAM clocked by the gated ~cpu_write did not work on the board
  integer ii; initial begin
    for (ii=0; ii<32; ii=ii+1) mem[0+ii] = INIT_00[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[32+ii] = INIT_01[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[64+ii] = INIT_02[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[96+ii] = INIT_03[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[128+ii] = INIT_04[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[160+ii] = INIT_05[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[192+ii] = INIT_06[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[224+ii] = INIT_07[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[256+ii] = INIT_08[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[288+ii] = INIT_09[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[320+ii] = INIT_0A[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[352+ii] = INIT_0B[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[384+ii] = INIT_0C[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[416+ii] = INIT_0D[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[448+ii] = INIT_0E[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[480+ii] = INIT_0F[8*ii +: 8];
  end
  always @(posedge CLKA) if (ENA) begin
    if (RSTA) DOA <= 8'h00; else if (WEA) begin mem[ADDRA] <= DIA; DOA <= DIA; end else DOA <= mem[ADDRA];
  end
  always @(posedge CLKB) if (ENB) begin
    if (RSTB) DOB <= 8'h00; else DOB <= mem[ADDRB];                    // port B only reads (WEB is tied low where this module is used: the palette); a second writing clock would need a clock-merging LUT
  end
endmodule

module ramb4_s8_s16 #(parameter [255:0] INIT_00 = 256'h0, parameter [255:0] INIT_01 = 256'h0, parameter [255:0] INIT_02 = 256'h0, parameter [255:0] INIT_03 = 256'h0, parameter [255:0] INIT_04 = 256'h0, parameter [255:0] INIT_05 = 256'h0, parameter [255:0] INIT_06 = 256'h0, parameter [255:0] INIT_07 = 256'h0, parameter [255:0] INIT_08 = 256'h0, parameter [255:0] INIT_09 = 256'h0, parameter [255:0] INIT_0A = 256'h0, parameter [255:0] INIT_0B = 256'h0, parameter [255:0] INIT_0C = 256'h0, parameter [255:0] INIT_0D = 256'h0, parameter [255:0] INIT_0E = 256'h0, parameter [255:0] INIT_0F = 256'h0) (input [8:0] ADDRA, input CLKA, input [7:0] DIA, input ENA, input RSTA, input WEA, output reg [7:0] DOA,
                    input [7:0] ADDRB, input CLKB, input [15:0] DIB, input ENB, input RSTB, input WEB, output reg [15:0] DOB);
  reg [7:0] mem [0:511];
  integer ii; initial begin
    for (ii=0; ii<32; ii=ii+1) mem[0+ii] = INIT_00[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[32+ii] = INIT_01[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[64+ii] = INIT_02[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[96+ii] = INIT_03[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[128+ii] = INIT_04[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[160+ii] = INIT_05[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[192+ii] = INIT_06[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[224+ii] = INIT_07[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[256+ii] = INIT_08[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[288+ii] = INIT_09[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[320+ii] = INIT_0A[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[352+ii] = INIT_0B[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[384+ii] = INIT_0C[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[416+ii] = INIT_0D[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[448+ii] = INIT_0E[8*ii +: 8];
    for (ii=0; ii<32; ii=ii+1) mem[480+ii] = INIT_0F[8*ii +: 8];
  end
  always @(posedge CLKA) if (ENA) begin
    if (RSTA) DOA <= 8'h00; else if (WEA) begin mem[ADDRA] <= DIA; DOA <= DIA; end else DOA <= mem[ADDRA];
  end
  always @(posedge CLKB) if (ENB) begin
    if (RSTB) DOB <= 16'h0000;
    else if (WEB) begin mem[{ADDRB,1'b0}] <= DIB[7:0]; mem[{ADDRB,1'b1}] <= DIB[15:8]; DOB <= DIB; end
    else DOB <= {mem[{ADDRB,1'b1}], mem[{ADDRB,1'b0}]};
  end
endmodule
